<?php
namespace App\Http\Controllers;
use App\Models\GoodsReceipt;use App\Models\Product;use App\Models\Store;use App\Models\StorePosition;use App\Models\Supplier;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\View\View;
class GoodsReceiptController extends Controller {
 public function index(Request $request):View{$f=$request->validate(['supplier'=>['nullable','integer'],'store'=>['nullable','integer'],'from'=>['nullable','date'],'to'=>['nullable','date'],'search'=>['nullable','string']]);$receipts=GoodsReceipt::query()->leftJoin('suppliers','goods_receipts.supplier_id','=','suppliers.id')->leftJoin('stores','goods_receipts.store_id','=','stores.id')->select('goods_receipts.*','suppliers.name as supplier_name','stores.name as store_name')->when($f['supplier']??null,fn($q,$v)=>$q->where('supplier_id',$v))->when($f['store']??null,fn($q,$v)=>$q->where('store_id',$v))->when($f['from']??null,fn($q,$v)=>$q->whereDate('mrr_date','>=',$v))->when($f['to']??null,fn($q,$v)=>$q->whereDate('mrr_date','<=',$v))->when($f['search']??null,fn($q,$v)=>$q->where('mrr_no','like',"%{$v}%"))->latest('mrr_date')->paginate(20)->withQueryString();return view('goods-receipts.index',['receipts'=>$receipts,'filters'=>$f,'suppliers'=>Supplier::where('is_active',true)->orderBy('name')->get(),'stores'=>Store::where('is_active',true)->orderBy('name')->get()]);}
 public function create():View{return view('goods-receipts.create',['nextNo'=>$this->next(),'suppliers'=>Supplier::where('is_active',true)->orderBy('name')->get(),'stores'=>Store::where('is_active',true)->orderBy('name')->get(),'positions'=>StorePosition::where('is_active',true)->orderBy('name')->get(),'products'=>Product::where('is_active',true)->orderBy('part_no')->get(['id','part_no','name','unit'])]);}
 public function store(Request $r){$d=$r->validate(['mrr_date'=>['required','date'],'payment_mode'=>['nullable','string'],'cash_head'=>['nullable','string'],'purchase_type'=>['required','string'],'currency'=>['required','string'],'exchange_rate'=>['required','numeric','min:0'],'store_id'=>['required','exists:stores,id'],'supplier_id'=>['required','exists:suppliers,id'],'po_no'=>['nullable','string'],'remarks'=>['nullable','string'],'items'=>['required','array','min:1'],'items.*.product_id'=>['required','distinct','exists:products,id'],'items.*.store_position_id'=>['nullable','exists:store_positions,id'],'items.*.quantity'=>['required','numeric','min:.01'],'items.*.rate'=>['required','numeric','min:0']]);DB::transaction(function()use($d,$r){$total=collect($d['items'])->sum(fn($x)=>$x['quantity']*$x['rate']);$g=GoodsReceipt::create(collect($d)->except('items')->all()+['mrr_no'=>$this->next(),'total_amount'=>$total,'user_id'=>$r->user()->id]);$g->items()->createMany(collect($d['items'])->map(fn($x)=>$x+['amount'=>$x['quantity']*$x['rate'],'landed_cost'=>$x['rate']*$d['exchange_rate']])->all());});return redirect()->route('goods-receipts.index')->with('success','Receive saved successfully.');}
 private function next():string{return 'MRR-'.now()->format('ymd').'-'.str_pad((string)(GoodsReceipt::whereDate('created_at',now()->toDateString())->count()+1),4,'0',STR_PAD_LEFT);}}
